package com.earthtrip.expense.adapter.in.web.api.v1.trips.by_trip_id.settlements.by_settlement_id.payments;import com.earthtrip.expense.application.port.in.SettlementUseCase;import com.earthtrip.sharedkernel.security.CurrentActor;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.Instant;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/trips/{tripId}/settlements/{settlementId}/payments") class SettlementPaymentsController{private final SettlementUseCase useCase;private final CurrentActor actor;SettlementPaymentsController(SettlementUseCase u,CurrentActor a){useCase=u;actor=a;}@GetMapping List<SettlementUseCase.PaymentResult>get(@PathVariable UUID tripId,@PathVariable UUID settlementId){return useCase.payments(tripId,settlementId,actor.requireUserId());}@PostMapping @ResponseStatus(HttpStatus.CREATED) SettlementUseCase.PaymentResult post(@PathVariable UUID tripId,@PathVariable UUID settlementId,@Valid @RequestBody PaymentMutation r){return useCase.createPayment(tripId,settlementId,actor.requireUserId(),new SettlementUseCase.PaymentCommand(r.requestId(),r.fromUserId(),r.toUserId(),r.amountMinor(),r.currency(),r.paidAt(),r.note(),0));}}
record PaymentMutation(@NotNull UUID requestId,@NotNull UUID fromUserId,@NotNull UUID toUserId,@Positive long amountMinor,@NotBlank String currency,Instant paidAt,String note){}
